ALTER TABLE "app"."workspaces" ADD CONSTRAINT "workspaces_accent_valid" CHECK ("app"."workspaces"."accent" is null or "app"."workspaces"."accent" in ('violet', 'blue', 'green', 'amber', 'cyan', 'pink') or "app"."workspaces"."accent" ~ '^#[0-9a-f]{6}$');